contracts/ComplianceStorage.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title ComplianceStorage
 * @dev Storage contract for compliance data
 */
contract ComplianceStorage {
    // Identity Registry
    address internal _identityRegistry;

    // Mapping of countries that are blocked or allowed
    mapping(uint16 => bool) internal _blockedCountries;

    // Maximum number of token holders
    uint256 internal _maxTokenHolders;

    // Current number of token holders (investors with balance > 0)
    uint256 internal _tokenHolderCount;

    // Mapping of investor address => has tokens
    mapping(address => bool) internal _hasTokens;
}

contracts/DividendManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/math/SafeMath.sol";

interface IERC3643 {
    function balanceOf(address account) external view returns (uint256);
    function totalSupply() external view returns (uint256);
}

/**
 * @title DividendManager
 * @dev Contract to manage dividend distributions for ERC3643 token holders
 */
contract DividendManager is Ownable, ReentrancyGuard {
    using SafeMath for uint256;

    // The ERC3643 token representing real estate shares
    IERC3643 public token;

    // The stablecoin used for dividend payments (e.g., USDC)
    IERC20 public dividendToken;

    // Annual dividend rate (5% = 500 basis points)
    uint256 public dividendRate = 500;

    // Basis points denominator (10000 = 100%)
    uint256 public constant BASIS_POINTS_DENOMINATOR = 10000;

    // Timestamp of the last dividend distribution
    uint256 public lastDistributionTimestamp;

    // Minimum interval between distributions (1 year in seconds)
    uint256 public constant DISTRIBUTION_INTERVAL = 365 days;

    // Mapping to track claimed dividends per distribution
    mapping(uint256 => mapping(address => bool)) public dividendClaimed;

    // Distribution ID counter
    uint256 public currentDistributionId;

    // Distribution details
    struct Distribution {
        uint256 timestamp;
        uint256 totalAmount;
        uint256 totalSupplySnapshot;
        bool finalized;
    }

    // Mapping of distribution ID to distribution details
    mapping(uint256 => Distribution) public distributions;

    // Events
    event DividendDistributionCreated(uint256 distributionId, uint256 amount, uint256 timestamp);
    event DividendClaimed(address indexed investor, uint256 distributionId, uint256 amount);
    event DividendRateUpdated(uint256 newRate);

    /**
     * @dev Constructor
     * @param _token Address of the ERC3643 token
     * @param _dividendToken Address of the stablecoin used for dividends
     */
    constructor(address _token, address _dividendToken) {
        require(_token != address(0), "Invalid token address");
        require(_dividendToken != address(0), "Invalid dividend token address");

        token = IERC3643(_token);
        dividendToken = IERC20(_dividendToken);
    }

    /**
     * @dev Updates the dividend rate
     * @param _newRate New dividend rate in basis points
     */
    function updateDividendRate(uint256 _newRate) external onlyOwner {
        require(_newRate <= 2000, "Rate cannot exceed 20%"); // Reasonable maximum cap
        dividendRate = _newRate;
        emit DividendRateUpdated(_newRate);
    }

    /**
     * @dev Creates a new dividend distribution
     * @param _totalAmount Total amount of stablecoins to distribute
     */
    function createDistribution(uint256 _totalAmount) external onlyOwner {
        require(
            block.timestamp >= lastDistributionTimestamp + DISTRIBUTION_INTERVAL,
            "Distribution interval not reached"
        );
        require(_totalAmount > 0, "Amount must be greater than 0");

        // Transfer stablecoins to this contract
        require(
            dividendToken.transferFrom(msg.sender, address(this), _totalAmount),
            "Transfer failed"
        );

        // Create new distribution
        currentDistributionId++;
        distributions[currentDistributionId] = Distribution({
            timestamp: block.timestamp,
            totalAmount: _totalAmount,
            totalSupplySnapshot: token.totalSupply(),
            finalized: true
        });

        lastDistributionTimestamp = block.timestamp;

        emit DividendDistributionCreated(currentDistributionId, _totalAmount, block.timestamp);
    }

    /**
     * @dev Allows an investor to claim their dividend for a specific distribution
     * @param _distributionId ID of the distribution to claim from
     */
    function claimDividend(uint256 _distributionId) external nonReentrant {
        require(_distributionId > 0 && _distributionId <= currentDistributionId, "Invalid distribution ID");
        require(!dividendClaimed[_distributionId][msg.sender], "Dividend already claimed");
        require(distributions[_distributionId].finalized, "Distribution not finalized");

        Distribution storage distribution = distributions[_distributionId];

        // Calculate investor's share based on token balance at distribution time
        uint256 investorBalance = token.balanceOf(msg.sender);
        require(investorBalance > 0, "No tokens held");

        uint256 investorShare = distribution.totalAmount.mul(investorBalance).div(distribution.totalSupplySnapshot);
        require(investorShare > 0, "No dividend to claim");

        // Mark as claimed
        dividendClaimed[_distributionId][msg.sender] = true;

        // Transfer dividend tokens to investor
        require(dividendToken.transfer(msg.sender, investorShare), "Transfer failed");

        emit DividendClaimed(msg.sender, _distributionId, investorShare);
    }

    /**
     * @dev Calculates the expected annual dividend for a token amount
     * @param _tokenAmount Amount of tokens
     * @return Expected annual dividend amount
     */
    function calculateExpectedDividend(uint256 _tokenAmount) external view returns (uint256) {
        // This is a simplified calculation that assumes property value = token supply
        return _tokenAmount.mul(dividendRate).div(BASIS_POINTS_DENOMINATOR);
    }
}

contracts/ERC3643Token.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/Pausable.sol";

/**
 * @title IIdentityRegistry
 * @dev Interface for the IdentityRegistry contract
 */
interface IIdentityRegistry {
    function isVerified(address _investor) external view returns (bool);
    function identity(address _investor) external view returns (address);
}

/**
 * @title ICompliance
 * @dev Interface for the Compliance contract
 */
interface ICompliance {
    function canTransfer(address _from, address _to, uint256 _amount) external view returns (bool);
    function addTokenHolder(address _to) external;
    function removeTokenHolder(address _from) external;
}

/**
 * @title IERC3643
 * @dev Interface for ERC-3643 tokens
 */
interface IERC3643 {
    function setIdentityRegistry(address _identityRegistry) external;
    function setCompliance(address _compliance) external;
    function pause() external;
    function unpause() external;
    function mint(address _to, uint256 _amount) external;
    function burn(address _from, uint256 _amount) external;
    function recoveryAddress(address _lostWallet, address _newWallet) external;
    function forcedTransfer(address _from, address _to, uint256 _amount) external returns (bool);
    function batchForcedTransfer(address[] calldata _fromList, address[] calldata _toList, uint256[] calldata _amounts) external returns (bool);
    function identityRegistry() external view returns (address);
    function compliance() external view returns (address);
    function decimals() external view returns (uint8);
}

/**
 * @title ERC3643Token
 * @dev Implementation of ERC-3643 token standard with fractionalization
 */
contract ERC3643Token is ERC20, Pausable, Ownable, IERC3643 {
    // Identity Registry contract address
    address private _identityRegistry;

    // Compliance contract address 
    address private _compliance;

    // List of agents that can perform certain actions
    mapping(address => bool) private _agents;

    // Property details
    string public propertyAddress;
    uint256 public propertyValue;
    uint256 public constant FRACTION_DECIMALS = 18;
    uint256 public constant SHARES_PER_PROPERTY = 1000;

    // Events
    event IdentityRegistrySet(address indexed identityRegistry);
    event ComplianceSet(address indexed compliance);
    event AgentAdded(address indexed agent);
    event AgentRemoved(address indexed agent);
    event AddressRecovered(address indexed lostWallet, address indexed newWallet, uint256 amount);
    event PropertyDetailsSet(string propertyAddress, uint256 propertyValue);
    event TokensFrozen(address indexed wallet, uint256 amount);
    event TokensUnfrozen(address indexed wallet, uint256 amount);

    // Mapping of frozen tokens per wallet
    mapping(address => uint256) private _frozenTokens;

    // Modifiers

    /**
     * @dev Modifier to check if the sender is an agent
     */
    modifier onlyAgent() {
        require(_agents[msg.sender], "ERC3643Token: Not an agent");
        _;
    }

    /**
     * @dev Constructor
     * @param name Token name
     * @param symbol Token symbol
     * @param identityRegistry_ Address of the identity registry
     * @param compliance_ Address of the compliance contract
     * @param propertyAddr Physical address of the property
     * @param propertyVal Value of the property
     */
    constructor(
        string memory name,
        string memory symbol,
        address identityRegistry_,
        address compliance_,
        string memory propertyAddr,
        uint256 propertyVal
    ) ERC20(name, symbol) {
        require(identityRegistry_ != address(0), "ERC3643Token: Invalid identity registry");
        require(compliance_ != address(0), "ERC3643Token: Invalid compliance");

        _identityRegistry = identityRegistry_;
        _compliance = compliance_;
        propertyAddress = propertyAddr;
        propertyValue = propertyVal;

        emit IdentityRegistrySet(identityRegistry_);
        emit ComplianceSet(compliance_);
        emit PropertyDetailsSet(propertyAddr, propertyVal);

        // Add deployer as an agent
        _agents[msg.sender] = true;
        emit AgentAdded(msg.sender);
    }

    /**
     * @dev Sets the identity registry
     * @param identityRegistry_ Address of the identity registry
     */
    function setIdentityRegistry(address identityRegistry_) external override onlyOwner {
        require(identityRegistry_ != address(0), "ERC3643Token: Invalid identity registry");
        _identityRegistry = identityRegistry_;
        emit IdentityRegistrySet(identityRegistry_);
    }

    /**
     * @dev Sets the compliance contract
     * @param compliance_ Address of the compliance contract
     */
    function setCompliance(address compliance_) external override onlyOwner {
        require(compliance_ != address(0), "ERC3643Token: Invalid compliance");
        _compliance = compliance_;
        emit ComplianceSet(compliance_);
    }

    /**
     * @dev Adds an agent
     * @param agent Address of the agent
     */
    function addAgent(address agent) external onlyOwner {
        require(agent != address(0), "ERC3643Token: Invalid agent");
        require(!_agents[agent], "ERC3643Token: Already an agent");
        _agents[agent] = true;
        emit AgentAdded(agent);
    }

    /**
     * @dev Removes an agent
     * @param agent Address of the agent
     */
    function removeAgent(address agent) external onlyOwner {
        require(_agents[agent], "ERC3643Token: Not an agent");
        _agents[agent] = false;
        emit AgentRemoved(agent);
    }

    /**
     * @dev Pauses the token (stops transfers)
     */
    function pause() external override onlyOwner {
        _pause();
    }

    /**
     * @dev Unpauses the token (allows transfers)
     */
    function unpause() external override onlyOwner {
        _unpause();
    }

    /**
     * @dev Sets the property details
     * @param propertyAddr Physical address of the property
     * @param propertyVal Value of the property
     */
    function setPropertyDetails(string calldata propertyAddr, uint256 propertyVal) external onlyOwner {
        require(bytes(propertyAddr).length > 0, "ERC3643Token: Invalid property address");
        require(propertyVal > 0, "ERC3643Token: Invalid property value");

        propertyAddress = propertyAddr;
        propertyValue = propertyVal;

        emit PropertyDetailsSet(propertyAddr, propertyVal);
    }

    /**
     * @dev Mints tokens to an address
     * @param to Address to mint tokens to
     * @param amount Amount of tokens to mint
     */
    function mint(address to, uint256 amount) external override onlyAgent {
        require(to != address(0), "ERC3643Token: Invalid address");
        require(amount > 0, "ERC3643Token: Invalid amount");

        // Check if the receiver is eligible
        require(IIdentityRegistry(_identityRegistry).isVerified(to), "ERC3643Token: Receiver not verified");
        require(ICompliance(_compliance).canTransfer(address(0), to, amount), "ERC3643Token: Transfer not compliant");

        // Update token holder count in compliance
        ICompliance(_compliance).addTokenHolder(to);

        // Mint tokens
        _mint(to, amount);
    }

    /**
     * @dev Burns tokens from an address
     * @param from Address to burn tokens from
     * @param amount Amount of tokens to burn
     */
    function burn(address from, uint256 amount) external override onlyAgent {
        require(from != address(0), "ERC3643Token: Invalid address");
        require(amount > 0, "ERC3643Token: Invalid amount");
        require(amount <= balanceOf(from) - _frozenTokens[from], "ERC3643Token: Insufficient unfrozen balance");

        // Update token holder count in compliance if balance becomes zero
        if (balanceOf(from) == amount) {
            ICompliance(_compliance).removeTokenHolder(from);
        }

        // Burn tokens
        _burn(from, amount);
    }

    /**
 * @dev Internal implementation of forced transfer
 * @param from Address to transfer tokens from
 * @param to Address to transfer tokens to
 * @param amount Amount of tokens to transfer
 * @return True if successful
 */
function _forcedTransfer(address from, address to, uint256 amount) internal returns (bool) {
    require(from != address(0) && to != address(0), "ERC3643Token: Invalid address");
    require(amount > 0, "ERC3643Token: Invalid amount");
    require(amount <= balanceOf(from), "ERC3643Token: Insufficient balance");

    // Check if the receiver is eligible
    require(IIdentityRegistry(_identityRegistry).isVerified(to), "ERC3643Token: Receiver not verified");
    require(ICompliance(_compliance).canTransfer(from, to, amount), "ERC3643Token: Transfer not compliant");

    // Update token holder count in compliance
    if (balanceOf(to) == 0 && amount > 0) {
        ICompliance(_compliance).addTokenHolder(to);
    }
    if (balanceOf(from) == amount) {
        ICompliance(_compliance).removeTokenHolder(from);
    }

    // Transfer tokens
    _transfer(from, to, amount);

    return true;
}

/**
 * @dev Forces a transfer of tokens from one address to another
 * @param from Address to transfer tokens from
 * @param to Address to transfer tokens to
 * @param amount Amount of tokens to transfer
 * @return True if successful
 */
function forcedTransfer(address from, address to, uint256 amount) external override onlyAgent returns (bool) {
    return _forcedTransfer(from, to, amount);
}

/**
 * @dev Forces multiple transfers of tokens
 * @param fromList Addresses to transfer tokens from
 * @param toList Addresses to transfer tokens to
 * @param amounts Amounts of tokens to transfer
 * @return True if successful
 */
function batchForcedTransfer(
    address[] calldata fromList,
    address[] calldata toList,
    uint256[] calldata amounts
) external override onlyAgent returns (bool) {
    require(
        fromList.length == toList.length && fromList.length == amounts.length,
        "ERC3643Token: Arrays length mismatch"
    );

    for (uint256 i = 0; i < fromList.length; i++) {
        require(_forcedTransfer(fromList[i], toList[i], amounts[i]), "ERC3643Token: Forced transfer failed");
    }

    return true;
}

    /**
     * @dev Recovers tokens from a lost wallet to a new wallet
     * @param lostWallet Address of the lost wallet
     * @param newWallet Address of the new wallet
     */
    function recoveryAddress(address lostWallet, address newWallet) external override onlyAgent {
        require(lostWallet != address(0) && newWallet != address(0), "ERC3643Token: Invalid address");
        require(lostWallet != newWallet, "ERC3643Token: Same addresses");
        require(balanceOf(lostWallet) > 0, "ERC3643Token: No tokens to recover");

        // Check if the new wallet is eligible
        require(IIdentityRegistry(_identityRegistry).isVerified(newWallet), "ERC3643Token: New wallet not verified");

        // Get the balance of the lost wallet
        uint256 amount = balanceOf(lostWallet);

        // Update token holder count in compliance
        ICompliance(_compliance).addTokenHolder(newWallet);
        ICompliance(_compliance).removeTokenHolder(lostWallet);

        // Transfer tokens
        _transfer(lostWallet, newWallet, amount);

        emit AddressRecovered(lostWallet, newWallet, amount);
    }

    /**
     * @dev Freezes tokens from a wallet
     * @param wallet Address of the wallet
     * @param amount Amount of tokens to freeze
     */
    function freezeTokens(address wallet, uint256 amount) external onlyAgent {
        require(wallet != address(0), "ERC3643Token: Invalid address");
        require(amount > 0, "ERC3643Token: Invalid amount");
        require(amount <= balanceOf(wallet) - _frozenTokens[wallet], "ERC3643Token: Insufficient unfrozen balance");

        _frozenTokens[wallet] += amount;

        emit TokensFrozen(wallet, amount);
    }

    /**
     * @dev Unfreezes tokens from a wallet
     * @param wallet Address of the wallet
     * @param amount Amount of tokens to unfreeze
     */
    function unfreezeTokens(address wallet, uint256 amount) external onlyAgent {
        require(wallet != address(0), "ERC3643Token: Invalid address");
        require(amount > 0, "ERC3643Token: Invalid amount");
        require(amount <= _frozenTokens[wallet], "ERC3643Token: Insufficient frozen balance");

        _frozenTokens[wallet] -= amount;

        emit TokensUnfrozen(wallet, amount);
    }

    /**
     * @dev Gets the frozen balance of a wallet
     * @param wallet Address of the wallet
     * @return Frozen balance
     */
    function getFrozenTokens(address wallet) external view returns (uint256) {
        return _frozenTokens[wallet];
    }

    /**
     * @dev Gets the unfrozen balance of a wallet
     * @param wallet Address of the wallet
     * @return Unfrozen balance
     */
    function getUnfrozenTokens(address wallet) external view returns (uint256) {
        return balanceOf(wallet) - _frozenTokens[wallet];
    }

    /**
     * @dev Gets the identity registry
     * @return Address of the identity registry
     */
    function identityRegistry() external view override returns (address) {
        return _identityRegistry;
    }

    /**
     * @dev Gets the compliance contract
     * @return Address of the compliance contract
     */
    function compliance() external view override returns (address) {
        return _compliance;
    }

    /**
     * @dev Checks if an address is an agent
     * @param agent Address to check
     * @return True if the address is an agent
     */
    function isAgent(address agent) external view returns (bool) {
        return _agents[agent];
    }

    /**
     * @dev Gets the decimals of the token
     * @return Number of decimals
     */
    function decimals() public view override(ERC20, IERC3643) returns (uint8) {
        return uint8(FRACTION_DECIMALS);
    }

    /**
     * @dev Gets the total shares of the property
     * @return Number of shares
     */
    function totalShares() external pure returns (uint256) {
        return SHARES_PER_PROPERTY;
    }

    /**
     * @dev Gets the value per token
     * @return Value per token
     */
    function valuePerToken() external view returns (uint256) {
        uint256 totalSupply_ = totalSupply();
        if (totalSupply_ == 0) {
            return 0;
        }
        return (propertyValue * (10 ** FRACTION_DECIMALS)) / totalSupply_;
    }

    /**
     * @dev Hook that is called before any transfer of tokens
     * @param from Address of the sender
     * @param to Address of the receiver
     * @param amount Amount of tokens to transfer
     */
    function _beforeTokenTransfer(address from, address to, uint256 amount) internal override whenNotPaused {
        super._beforeTokenTransfer(from, to, amount);

        // Skip checks for minting and burning
        if (from == address(0) || to == address(0)) {
            return;
        }

        // Check if sender has enough unfrozen tokens
        require(amount <= balanceOf(from) - _frozenTokens[from], "ERC3643Token: Insufficient unfrozen balance");

        // Check if both sender and receiver are verified
        require(IIdentityRegistry(_identityRegistry).isVerified(from), "ERC3643Token: Sender not verified");
        require(IIdentityRegistry(_identityRegistry).isVerified(to), "ERC3643Token: Receiver not verified");

        // Check if the transfer is compliant
        require(ICompliance(_compliance).canTransfer(from, to, amount), "ERC3643Token: Transfer not compliant");

        // Update token holder count in compliance
        if (balanceOf(to) == 0 && amount > 0) {
            ICompliance(_compliance).addTokenHolder(to);
        }
        if (balanceOf(from) == amount) {
            ICompliance(_compliance).removeTokenHolder(from);
        }
    }
}

contracts/IdentityRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title IClaimTopicsRegistry
 * @dev Interface for the ClaimTopicsRegistry contract
 */
interface IClaimTopicsRegistry {
    function getClaimTopics() external view returns (uint256[] memory);
}

/**
 * @title ITrustedIssuersRegistry
 * @dev Interface for the TrustedIssuersRegistry contract
 */
interface ITrustedIssuersRegistry {
    function getTrustedIssuers() external view returns (address[] memory);
    function isTrustedIssuer(address _issuer) external view returns (bool);
    function getTrustedIssuerClaimTopics(address _trustedIssuer) external view returns (uint256[] memory);
}

/**
 * @title IIdentity
 * @dev Interface for ERC-734 & ERC-735 (Identity and claims)
 */
interface IIdentity {
    function keyHasPurpose(bytes32 _key, uint256 _purpose) external view returns (bool);
    function getKey(bytes32 _key) external view returns (uint256 purpose, bytes32 keyType, bytes32 key);
    function getClaim(bytes32 _claimId) external view returns (
        uint256 topic,
        uint256 scheme,
        address issuer,
        bytes memory signature,
        bytes memory data,
        string memory uri
    );
    function getClaimIdsByTopic(uint256 _topic) external view returns (bytes32[] memory);
}

/**
 * @title IIdentityRegistryStorage
 * @dev Interface for the IdentityRegistryStorage contract
 */
interface IIdentityRegistryStorage {
    function storeIdentity(address _investorAddress, address _identity, uint16 _countryCode) external;
    function removeIdentity(address _investorAddress) external;
    function updateCountry(address _investorAddress, uint16 _countryCode) external;
    function getIdentity(address _investorAddress) external view returns (address);
    function getCountry(address _investorAddress) external view returns (uint16);
}

/**
 * @title IdentityRegistry
 * @dev Registry for ERC-3643 identities with validation against trusted issuers
 */
contract IdentityRegistry is Ownable {
    // Addresses of trusted contracts
    address private _trustedIssuersRegistry;
    address private _claimTopicsRegistry;
    address private _identityStorage;

    // Mapping of agent addresses
    mapping(address => bool) private _agents;

    // Events
    event IdentityRegistered(address indexed investorAddress, address identity, uint16 countryCode);
    event IdentityRemoved(address indexed investorAddress);
    event CountryUpdated(address indexed investorAddress, uint16 countryCode);
    event TrustedIssuersRegistrySet(address indexed trustedIssuersRegistry);
    event ClaimTopicsRegistrySet(address indexed claimTopicsRegistry);
    event IdentityStorageSet(address indexed identityStorage);
    event AgentAdded(address indexed agent);
    event AgentRemoved(address indexed agent);

    /**
     * @dev Modifier to check if the sender is an agent
     */
    modifier onlyAgent() {
        require(_agents[msg.sender] || msg.sender == owner(), "IdentityRegistry: Not an agent");
        _;
    }

    /**
     * @dev Constructor
     * @param trustedIssuersRegistry Address of the trusted issuers registry
     * @param claimTopicsRegistry Address of the claim topics registry
     * @param identityStorage Address of the identity storage
     */
    constructor(
        address trustedIssuersRegistry, 
        address claimTopicsRegistry, 
        address identityStorage
    ) {
        setTrustedIssuersRegistry(trustedIssuersRegistry);
        setClaimTopicsRegistry(claimTopicsRegistry);
        setIdentityStorage(identityStorage);
    }

    /**
     * @dev Sets the trusted issuers registry
     * @param trustedIssuersRegistry Address of the trusted issuers registry
     */
    function setTrustedIssuersRegistry(address trustedIssuersRegistry) public onlyOwner {
        require(trustedIssuersRegistry != address(0), "IdentityRegistry: Invalid address");
        _trustedIssuersRegistry = trustedIssuersRegistry;
        emit TrustedIssuersRegistrySet(trustedIssuersRegistry);
    }

    /**
     * @dev Sets the claim topics registry
     * @param claimTopicsRegistry Address of the claim topics registry
     */
    function setClaimTopicsRegistry(address claimTopicsRegistry) public onlyOwner {
        require(claimTopicsRegistry != address(0), "IdentityRegistry: Invalid address");
        _claimTopicsRegistry = claimTopicsRegistry;
        emit ClaimTopicsRegistrySet(claimTopicsRegistry);
    }

    /**
     * @dev Sets the identity storage
     * @param identityStorage Address of the identity storage
     */
    function setIdentityStorage(address identityStorage) public onlyOwner {
        require(identityStorage != address(0), "IdentityRegistry: Invalid address");
        _identityStorage = identityStorage;
        emit IdentityStorageSet(identityStorage);
    }

    /**
     * @dev Adds an agent
     * @param agent Address of the agent
     */
    function addAgent(address agent) external onlyOwner {
        require(agent != address(0), "IdentityRegistry: Invalid address");
        require(!_agents[agent], "IdentityRegistry: Already an agent");
        _agents[agent] = true;
        emit AgentAdded(agent);
    }

    /**
     * @dev Removes an agent
     * @param agent Address of the agent
     */
    function removeAgent(address agent) external onlyOwner {
        require(_agents[agent], "IdentityRegistry: Not an agent");
        _agents[agent] = false;
        emit AgentRemoved(agent);
    }

    /**
     * @dev Registers an identity for an investor
     * @param investorAddress Address of the investor
     * @param identity Address of the identity contract
     * @param countryCode Country code of the investor
     */
    function registerIdentity(address investorAddress, address identity, uint16 countryCode) external onlyAgent {
        require(investorAddress != address(0), "IdentityRegistry: Invalid address");
        require(identity != address(0), "IdentityRegistry: Invalid identity");
        require(IIdentityRegistryStorage(_identityStorage).getIdentity(investorAddress) == address(0), "IdentityRegistry: Identity already registered");

        IIdentityRegistryStorage(_identityStorage).storeIdentity(investorAddress, identity, countryCode);

        emit IdentityRegistered(investorAddress, identity, countryCode);
    }

    /**
     * @dev Updates the country code of an investor
     * @param investorAddress Address of the investor
     * @param countryCode New country code
     */
    function updateCountry(address investorAddress, uint16 countryCode) external onlyAgent {
        require(IIdentityRegistryStorage(_identityStorage).getIdentity(investorAddress) != address(0), "IdentityRegistry: Identity not registered");

        IIdentityRegistryStorage(_identityStorage).updateCountry(investorAddress, countryCode);

        emit CountryUpdated(investorAddress, countryCode);
    }

    /**
     * @dev Removes an identity from the registry
     * @param investorAddress Address of the investor
     */
    function deleteIdentity(address investorAddress) external onlyAgent {
        require(IIdentityRegistryStorage(_identityStorage).getIdentity(investorAddress) != address(0), "IdentityRegistry: Identity not registered");

        IIdentityRegistryStorage(_identityStorage).removeIdentity(investorAddress);

        emit IdentityRemoved(investorAddress);
    }

    /**
     * @dev Checks if an identity is verified against the trusted issuers
     * @param investorAddress Address of the investor
     * @return True if the identity is verified
     */
    function isVerified(address investorAddress) external view returns (bool) {
        address identity = IIdentityRegistryStorage(_identityStorage).getIdentity(investorAddress);

        // If no identity is registered, return false
        if (identity == address(0)) {
            return false;
        }

        // Get required claim topics
        uint256[] memory claimTopics = IClaimTopicsRegistry(_claimTopicsRegistry).getClaimTopics();

        // Get trusted issuers
        address[] memory trustedIssuers = ITrustedIssuersRegistry(_trustedIssuersRegistry).getTrustedIssuers();

        // Check each claim topic
        for (uint256 i = 0; i < claimTopics.length; i++) {
            uint256 claimTopic = claimTopics[i];

            // Get all claims for this topic
            bytes32[] memory claimIds = IIdentity(identity).getClaimIdsByTopic(claimTopic);

            bool claimValid = false;

            // Check each claim
            for (uint256 j = 0; j < claimIds.length; j++) {
                bytes32 claimId = claimIds[j];

                (uint256 topic, uint256 scheme, address issuer, bytes memory signature, bytes memory data, string memory uri) = IIdentity(identity).getClaim(claimId);


                // Check if issuer is trusted for this claim topic
                if (topic == claimTopic && 
                    ITrustedIssuersRegistry(_trustedIssuersRegistry).isTrustedIssuer(issuer)) {

                    uint256[] memory issuerClaimTopics = 
                        ITrustedIssuersRegistry(_trustedIssuersRegistry).getTrustedIssuerClaimTopics(issuer);

                    // Check if this issuer is trusted for this specific claim topic
                    for (uint256 k = 0; k < issuerClaimTopics.length; k++) {
                        if (issuerClaimTopics[k] == claimTopic) {
                            // Verify the claim by checking if the key has claim signing purpose (3)
                            bytes32 key = keccak256(abi.encode(issuer, claimTopic));

                            if (IIdentity(issuer).keyHasPurpose(key, 3)) {
                                claimValid = true;
                                break;
                            }
                        }
                    }
                }

                if (claimValid) {
                    break;
                }
            }

            if (!claimValid) {
                return false;
            }
        }

        return true;
    }

    /**
     * @dev Gets the identity of an investor
     * @param investorAddress Address of the investor
     * @return Address of the identity contract
     */
    function getIdentity(address investorAddress) external view returns (address) {
        return IIdentityRegistryStorage(_identityStorage).getIdentity(investorAddress);
    }

    /**
     * @dev Gets the country code of an investor
     * @param investorAddress Address of the investor
     * @return Country code
     */
    function investorCountry(address investorAddress) external view returns (uint16) {
        return IIdentityRegistryStorage(_identityStorage).getCountry(investorAddress);
    }

    /**
     * @dev Gets the trusted issuers registry
     * @return Address of the trusted issuers registry
     */
    function getTrustedIssuersRegistry() external view returns (address) {
        return _trustedIssuersRegistry;
    }

    /**
     * @dev Gets the claim topics registry
     * @return Address of the claim topics registry
     */
    function getClaimTopicsRegistry() external view returns (address) {
        return _claimTopicsRegistry;
    }

    /**
     * @dev Gets the identity storage
     * @return Address of the identity storage
     */
    function getIdentityStorage() external view returns (address) {
        return _identityStorage;
    }

    /**
     * @dev Checks if an address is an agent
     * @param agent Address of the agent
     * @return True if the address is an agent
     */
    function isAgent(address agent) external view returns (bool) {
        return _agents[agent];
    }
}

contracts/IdentityRegistryStorage.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title IdentityRegistryStorage
 * @dev Storage contract for identity registry data, separating storage from business logic
 */
contract IdentityRegistryStorage is Ownable {
    // Mapping of wallet address => identity contract
    mapping(address => address) private _identities;

    // Mapping of wallet address => country code (ISO 3166-1 numeric)
    mapping(address => uint16) private _countryCodes;

    // List of Identity Registries allowed to interact with this storage
    mapping(address => bool) private _authorizedRegistries;

    // Events
    event IdentityStored(address indexed investorAddress, address identity, uint16 countryCode);
    event IdentityRemoved(address indexed investorAddress);
    event CountryUpdated(address indexed investorAddress, uint16 countryCode);
    event RegistryAuthorized(address indexed registry);
    event RegistryUnauthorized(address indexed registry);

    /**
     * @dev Modifier to check if the sender is authorized
     */
    modifier onlyAuthorizedRegistry() {
        require(_authorizedRegistries[msg.sender], "IdentityRegistryStorage: Unauthorized registry");
        _;
    }

    /**
     * @dev Authorizes a registry to interact with this storage
     * @param registry Address of the registry to authorize
     */
    function authorizeRegistry(address registry) external onlyOwner {
        require(registry != address(0), "IdentityRegistryStorage: Invalid address");
        require(!_authorizedRegistries[registry], "IdentityRegistryStorage: Already authorized");

        _authorizedRegistries[registry] = true;

        emit RegistryAuthorized(registry);
    }

    /**
     * @dev Removes authorization from a registry
     * @param registry Address of the registry to unauthorize
     */
    function unauthorizeRegistry(address registry) external onlyOwner {
        require(_authorizedRegistries[registry], "IdentityRegistryStorage: Not authorized");

        _authorizedRegistries[registry] = false;

        emit RegistryUnauthorized(registry);
    }

    /**
     * @dev Stores an identity for an investor
     * @param investorAddress Address of the investor
     * @param identity Address of the identity contract
     * @param countryCode Country code of the investor
     */
    function storeIdentity(address investorAddress, address identity, uint16 countryCode) external onlyAuthorizedRegistry {
        require(investorAddress != address(0), "IdentityRegistryStorage: Invalid address");
        require(identity != address(0), "IdentityRegistryStorage: Invalid identity");

        _identities[investorAddress] = identity;
        _countryCodes[investorAddress] = countryCode;

        emit IdentityStored(investorAddress, identity, countryCode);
    }

    /**
     * @dev Removes an identity from storage
     * @param investorAddress Address of the investor
     */
    function removeIdentity(address investorAddress) external onlyAuthorizedRegistry {
        require(_identities[investorAddress] != address(0), "IdentityRegistryStorage: Identity not found");

        delete _identities[investorAddress];
        delete _countryCodes[investorAddress];

        emit IdentityRemoved(investorAddress);
    }

    /**
     * @dev Updates the country code of an investor
     * @param investorAddress Address of the investor
     * @param countryCode New country code
     */
    function updateCountry(address investorAddress, uint16 countryCode) external onlyAuthorizedRegistry {
        require(_identities[investorAddress] != address(0), "IdentityRegistryStorage: Identity not found");

        _countryCodes[investorAddress] = countryCode;

        emit CountryUpdated(investorAddress, countryCode);
    }

    /**
     * @dev Gets the identity of an investor
     * @param investorAddress Address of the investor
     * @return Address of the identity contract
     */
    function getIdentity(address investorAddress) external view returns (address) {
        return _identities[investorAddress];
    }

    /**
     * @dev Gets the country code of an investor
     * @param investorAddress Address of the investor
     * @return Country code
     */
    function getCountry(address investorAddress) external view returns (uint16) {
        return _countryCodes[investorAddress];
    }

    /**
     * @dev Checks if a registry is authorized
     * @param registry Address of the registry
     * @return True if the registry is authorized
     */
    function isRegistryAuthorized(address registry) external view returns (bool) {
        return _authorizedRegistries[registry];
    }
}

