contracts/RealEstateSecurityManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/math/SafeMath.sol";

interface IERC3643Token {
    function balanceOf(address account) external view returns (uint256);
    function totalSupply() external view returns (uint256);
    function mint(address to, uint256 amount) external;
    function addAgent(address agent) external;
    function removeAgent(address agent) external;
}

interface IDividendManager {
    function createDistribution(uint256 _totalAmount)    external;
    function updateDividendRate(uint256 _newRate) external;
}

interface IVestingManager {
    function registerInvestment(address _investor, uint256 _amount) external;
    function addToRedemptionReserve(uint256 _amount) external;
    function updateEarlyRedemptionPenalty(uint256 _newPenalty) external;
}

interface ISecondaryMarket {
    function updatePlatformFee(uint256 _newFee) external;
    function withdrawFees(address _recipient) external;
}

/**
 * @title RealEstateSecurityManager
 * @dev Central management contract for the real estate security token system
 */
contract RealEstateSecurityManager is Ownable, ReentrancyGuard {
    using SafeMath for uint256;

    // Core contracts
    IERC3643Token public token;
    IERC20 public stablecoin;
    IDividendManager public dividendManager;
    IVestingManager public vestingManager;
    ISecondaryMarket public secondaryMarket;

    // Fee recipient address
    address public feeRecipient;

    // Annual dividend rate (5% = 500 basis points)
    uint256 public annualDividendRate = 500;

    // Last dividend distribution timestamp
    uint256 public lastDividendTimestamp;

    // Events
    event TokensMinted(address indexed investor, uint256 amount);
    event DividendDistributed(uint256 amount, uint256 timestamp);
    event RedemptionReserveFunded(uint256 amount, uint256 timestamp);
    event FeeRecipientUpdated(address indexed newRecipient);
    event DividendRateUpdated(uint256 newRate);   



    /**
     * @dev Constructor
     * @param _token Address of the ERC3643 token
     * @param _stablecoin Address of the stablecoin
     * @param _dividendManager Address of the dividend manager
     * @param _vestingManager Address of the vesting manager
     * @param _secondaryMarket Address of the secondary market
     * @param _feeRecipient Address to receive fees
     */
    constructor(
        address _token,
        address _stablecoin,
        address _dividendManager,
        address _vestingManager,
        address _secondaryMarket,
        address _feeRecipient
    ) {
        require(_token != address(0), "Invalid token address");
        require(_stablecoin != address(0), "Invalid stablecoin address");
        require(_dividendManager != address(0), "Invalid dividend manager address");
        require(_vestingManager != address(0), "Invalid vesting manager address");
        require(_secondaryMarket != address(0), "Invalid secondary market address");
        require(_feeRecipient != address(0), "Invalid fee recipient address");

        token = IERC3643Token(_token);
        stablecoin = IERC20(_stablecoin);
        dividendManager = IDividendManager(_dividendManager);
        vestingManager = IVestingManager(_vestingManager);
        secondaryMarket = ISecondaryMarket(_secondaryMarket);
        feeRecipient = _feeRecipient;

    }

function initialize() external onlyOwner {
    dividendManager.updateDividendRate(annualDividendRate);
}


    /**
     * @dev Mints new tokens to an investor and registers their investment
     * @param _investor Address of the investor
     * @param _tokenAmount Amount of tokens to mint
     */
    function mintTokens(address _investor, uint256 _tokenAmount) external onlyOwner {
        require(_investor != address(0), "Invalid investor address");
        require(_tokenAmount > 0, "Invalid token amount");

        // Mint tokens to the investor
        token.mint(_investor, _tokenAmount);

        // Register investment in vesting manager
        vestingManager.registerInvestment(_investor, _tokenAmount);

        emit TokensMinted(_investor, _tokenAmount);
    }

    /**
     * @dev Distributes annual dividends
     * @param _totalAmount Total amount of stablecoins for dividend distribution
     */
    function distributeDividends(uint256 _totalAmount) external onlyOwner nonReentrant {
        require(_totalAmount > 0, "Invalid amount");

        // Transfer stablecoins to dividend manager
        require(
            stablecoin.transferFrom(msg.sender, address(this), _totalAmount),
            "Stablecoin transfer failed"
        );

        // Approve dividend manager to spend the tokens
        stablecoin.approve(address(dividendManager), _totalAmount);

        // Create dividend distribution
        dividendManager.createDistribution(_totalAmount);

        lastDividendTimestamp = block.timestamp;

        emit DividendDistributed(_totalAmount, block.timestamp);
    }

    /**
     * @dev Funds the redemption reserve for token buybacks
     * @param _amount Amount of stablecoins to add to redemption reserve
     */
    function fundRedemptionReserve(uint256 _amount) external onlyOwner nonReentrant {
        require(_amount > 0, "Invalid amount");

        // Transfer stablecoins to vesting manager
        require(
            stablecoin.transferFrom(msg.sender, address(this), _amount),
            "Stablecoin transfer failed"
        );

        // Approve vesting manager to spend the tokens
        stablecoin.approve(address(vestingManager), _amount);

        // Add to redemption reserve
        vestingManager.addToRedemptionReserve(_amount);

        emit RedemptionReserveFunded(_amount, block.timestamp);
    }

    /**
     * @dev Withdraws secondary market fees
     */
    function withdrawMarketFees() external onlyOwner {
        secondaryMarket.withdrawFees(feeRecipient);
    }

    /**
     * @dev Updates the fee recipient address
     * @param _newRecipient New fee recipient address
     */
    function updateFeeRecipient(address _newRecipient) external onlyOwner {
        require(_newRecipient != address(0), "Invalid recipient address");
        feeRecipient = _newRecipient;
        emit FeeRecipientUpdated(_newRecipient);
    }

    /**
     * @dev Updates the annual dividend rate
     * @param _newRate New dividend rate in basis points
     */
    function updateDividendRate(uint256 _newRate) external onlyOwner {
        require(_newRate <= 2000, "Rate cannot exceed 20%");
        annualDividendRate = _newRate;
        dividendManager.updateDividendRate(_newRate);
        emit DividendRateUpdated(_newRate);
    }

    /**
     * @dev Updates the early redemption penalty
     * @param _newPenalty New penalty rate in basis points
     */
    function updateEarlyRedemptionPenalty(uint256 _newPenalty) external onlyOwner {
        vestingManager.updateEarlyRedemptionPenalty(_newPenalty);
    }

    /**
     * @dev Updates the secondary market platform fee
     * @param _newFee New fee in basis points
     */
    function updatePlatformFee(uint256 _newFee) external onlyOwner {
        secondaryMarket.updatePlatformFee(_newFee);
    }

    /**
     * @dev Sets system contracts as agents on the token
     */
    function setupAgents() external onlyOwner {
        token.addAgent(address(vestingManager));
        token.addAgent(address(this));
    }

    /**
     * @dev Calculates expected annual dividend based on current token supply and rate
     * @return Expected annual dividend amount
     */
    function calculateAnnualDividend() external view returns (uint256) {
        uint256 totalSupply = token.totalSupply();
        return totalSupply.mul(annualDividendRate).div(10000);
    }
}

contracts/SecondaryMarket.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/math/SafeMath.sol";

interface IERC3643Token {
    function balanceOf(address account) external view returns (uint256);
    function totalSupply() external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function unfreezeTokens(address wallet, uint256 amount) external; // Add this line
}

interface IVestingManager {
    function getRedemptionStatus(address _investor) external view returns (
        bool canRedeemEarly,
        bool canRedeemFully,
        uint256 timeUntilEarlyRedemption,
        uint256 timeUntilFullRedemption
    );
}

/**
 * @title SecondaryMarket
 * @dev Facilitates secondary market trading of real estate tokens after the early redemption period
 */
contract SecondaryMarket is Ownable, ReentrancyGuard {
    using SafeMath for uint256;

    // The ERC3643 token representing real estate shares
    IERC3643Token public realEstateToken;

    // The stablecoin used for payments
    IERC20 public paymentToken;

    // Reference to vesting manager to check lockup status
    IVestingManager public vestingManager;

    // Platform fee in basis points (0.5% = 50 basis points)
    uint256 public platformFee = 50;

    // Basis points denominator (10000 = 100%)
    uint256 public constant BASIS_POINTS_DENOMINATOR = 10000;

    // Sell order structure
    struct SellOrder {
        address seller;
        uint256 tokenAmount;
        uint256 pricePerToken;
        uint256 timestamp;
        bool active;
    }

    // Mapping of order ID to sell order
    mapping(uint256 => SellOrder) public sellOrders;

    // Order ID counter
    uint256 public nextOrderId = 1;

    // Total platform fees collected
    uint256 public totalFeesCollected;

    // Events
    event SellOrderCreated(uint256 indexed orderId, address indexed seller, uint256 tokenAmount, uint256 pricePerToken);
    event SellOrderCancelled(uint256 indexed orderId);
    event TokensPurchased(uint256 indexed orderId, address indexed buyer, address indexed seller, uint256 tokenAmount, uint256 totalPrice);
    event PlatformFeeUpdated(uint256 newFee);
    event FeesWithdrawn(address indexed recipient, uint256 amount);

    /**
     * @dev Constructor
     * @param _token Address of the ERC3643 token
     * @param _paymentToken Address of the payment token
     * @param _vestingManager Address of the vesting manager
     */
    constructor(
        address _token,
        address _paymentToken,
        address _vestingManager
    ) {
        require(_token != address(0), "Invalid token address");
        require(_paymentToken != address(0), "Invalid payment token address");
        require(_vestingManager != address(0), "Invalid vesting manager address");

        realEstateToken = IERC3643Token(_token);
        paymentToken = IERC20(_paymentToken);
        vestingManager = IVestingManager(_vestingManager);
    }

    /**
     * @dev Creates a new sell order
     * @param _tokenAmount Amount of tokens to sell
     * @param _pricePerToken Price per token in payment tokens
     */
    function createSellOrder(uint256 _tokenAmount, uint256 _pricePerToken) external nonReentrant {
    require(_tokenAmount > 0, "Amount must be greater than 0");
    require(_pricePerToken > 0, "Price must be greater than 0");
    require(realEstateToken.balanceOf(msg.sender) >= _tokenAmount, "Insufficient token balance");

    // Check if tokens are approved for transfer by SecondaryMarket
uint256 allowance = IERC20(address(realEstateToken)).allowance(msg.sender, address(this));
    require(allowance >= _tokenAmount, "Insufficient token allowance for sale");

    // Optional: confirm vestingManager check for unlock
    (bool canRedeemEarly, , , ) = vestingManager.getRedemptionStatus(msg.sender);
    require(canRedeemEarly, "Tokens are still in lockup period");

    // Save sell order info without actually transferring tokens
    uint256 orderId = nextOrderId++;
    sellOrders[orderId] = SellOrder({
        seller: msg.sender,
        tokenAmount: _tokenAmount,
        pricePerToken: _pricePerToken,
        timestamp: block.timestamp,
        active: true
    });

    emit SellOrderCreated(orderId, msg.sender, _tokenAmount, _pricePerToken);
}


    /**
     * @dev Cancels a sell order and returns tokens to seller
     * @param _orderId ID of the order to cancel
     */
    function cancelSellOrder(uint256 _orderId) external nonReentrant {
    SellOrder storage order = sellOrders[_orderId];

    require(order.active, "Order not active");
    require(msg.sender == order.seller, "Not the seller");

    // Simply mark the order as inactive - no token transfer needed
    order.active = false;

    // No need to transfer tokens back, as they were never transferred to the contract

    emit SellOrderCancelled(_orderId);
}

    /**
     * @dev Purchases tokens from a sell order
     * @param _orderId ID of the order to purchase from
     * @param _tokenAmount Amount of tokens to purchase
     */
    function purchaseTokens(uint256 _orderId, uint256 _tokenAmount) external nonReentrant {
    SellOrder storage order = sellOrders[_orderId];

    require(order.active, "Order not active");
    require(_tokenAmount > 0 && _tokenAmount <= order.tokenAmount, "Invalid token amount");

    // Calculate total price and platform fee
    uint256 totalPrice = _tokenAmount.mul(order.pricePerToken).div(1e18); // Add decimal adjustment
    uint256 platformFeeAmount = totalPrice.mul(platformFee).div(BASIS_POINTS_DENOMINATOR);
    uint256 sellerAmount = totalPrice.sub(platformFeeAmount);

    // Transfer payment tokens from buyer
    require(paymentToken.transferFrom(msg.sender, address(this), totalPrice), "Payment transfer failed");

    // Transfer tokens directly from seller to buyer instead of from this contract
    require(realEstateToken.transferFrom(order.seller, msg.sender, _tokenAmount), "Token transfer failed");

    // Transfer payment to seller minus fee
    require(paymentToken.transfer(order.seller, sellerAmount), "Seller payment failed");

    // Update platform fees collected
    totalFeesCollected = totalFeesCollected.add(platformFeeAmount);

    // Update order
    order.tokenAmount = order.tokenAmount.sub(_tokenAmount);
    if (order.tokenAmount == 0) {
        order.active = false;
    }

    emit TokensPurchased(_orderId, msg.sender, order.seller, _tokenAmount, totalPrice);
}

    /**
     * @dev Updates the platform fee
     * @param _newFee New fee in basis points
     */
    function updatePlatformFee(uint256 _newFee) external onlyOwner {
        require(_newFee <= 300, "Fee cannot exceed 3%");
        platformFee = _newFee;
        emit PlatformFeeUpdated(_newFee);
    }

    /**
     * @dev Withdraws collected fees
     * @param _recipient Address to receive the fees
     */
    function withdrawFees(address _recipient) external onlyOwner {
        require(_recipient != address(0), "Invalid recipient");
        require(totalFeesCollected > 0, "No fees to withdraw");

        uint256 amount = totalFeesCollected;
        totalFeesCollected = 0;

        require(paymentToken.transfer(_recipient, amount), "Fee transfer failed");

        emit FeesWithdrawn(_recipient, amount);
    }

    /**
     * @dev Gets all active sell orders
     * @return orderIds Array of active order IDs
     */
    function getActiveSellOrders() external view returns (uint256[] memory) {
        uint256 activeCount = 0;

        // Count active orders
        for (uint256 i = 1; i < nextOrderId; i++) {
            if (sellOrders[i].active) {
                activeCount++;
            }
        }

        // Create result array
        uint256[] memory result = new uint256[](activeCount);
        uint256 index = 0;

        // Populate result array
        for (uint256 i = 1; i < nextOrderId; i++) {
            if (sellOrders[i].active) {
                result[index] = i;
                index++;
            }
        }

        return result;
    }

    /**
     * @dev Gets sell order details
     * @param _orderId ID of the order
     * @return seller The seller address
     * @return tokenAmount The token amount available
     * @return pricePerToken Price per token
     * @return timestamp Creation timestamp
     * @return active Whether the order is active
     */
    function getSellOrder(uint256 _orderId) external view returns (
        address seller,
        uint256 tokenAmount,
        uint256 pricePerToken,
        uint256 timestamp,
        bool active
    ) {
        SellOrder storage order = sellOrders[_orderId];
        return (
            order.seller,
            order.tokenAmount,
            order.pricePerToken,
            order.timestamp,
            order.active
        );
    }
}

contracts/TrustedIssuerRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title TrustedIssuersRegistry
 * @dev Registry for trusted claim issuers in the ERC-3643 token system
 */
contract TrustedIssuersRegistry is Ownable {
    // Array of trusted issuers
    address[] private _trustedIssuers;

    // Mapping of trusted issuer => index in _trustedIssuers (index+1 to handle 0 as default value)
    mapping(address => uint256) private _trustedIssuerIndex;

    // Mapping of trusted issuer => claim topics they can issue
    mapping(address => uint256[]) private _trustedIssuerClaimTopics;

    // Events
    event TrustedIssuerAdded(address indexed trustedIssuer, uint256[] claimTopics);
    event TrustedIssuerRemoved(address indexed trustedIssuer);
    event TrustedIssuerClaimTopicsUpdated(address indexed trustedIssuer, uint256[] claimTopics);

    /**
     * @dev Adds a trusted issuer with their claim topics
     * @param trustedIssuer Address of the trusted issuer
     * @param claimTopics Array of claim topics the issuer can issue
     */
    function addTrustedIssuer(address trustedIssuer, uint256[] calldata claimTopics) external onlyOwner {
        require(trustedIssuer != address(0), "TrustedIssuersRegistry: Invalid address");
        require(claimTopics.length > 0, "TrustedIssuersRegistry: Empty claim topics");
        require(_trustedIssuerIndex[trustedIssuer] == 0, "TrustedIssuersRegistry: Already registered");

        // Add to the array
        _trustedIssuers.push(trustedIssuer);

        // Set the index (+1 to handle 0 as default)
        _trustedIssuerIndex[trustedIssuer] = _trustedIssuers.length;

        // Set the claim topics
        _trustedIssuerClaimTopics[trustedIssuer] = claimTopics;

        emit TrustedIssuerAdded(trustedIssuer, claimTopics);
    }

    /**
     * @dev Removes a trusted issuer
     * @param trustedIssuer Address of the trusted issuer
     */
    function removeTrustedIssuer(address trustedIssuer) external onlyOwner {
        require(_trustedIssuerIndex[trustedIssuer] != 0, "TrustedIssuersRegistry: Not registered");

        // Calculate real index (stored index - 1)
        uint256 index = _trustedIssuerIndex[trustedIssuer] - 1;
        uint256 lastIndex = _trustedIssuers.length - 1;

        if (index != lastIndex) {
            // Move the last element to the removed position
            address lastIssuer = _trustedIssuers[lastIndex];
            _trustedIssuers[index] = lastIssuer;
            _trustedIssuerIndex[lastIssuer] = index + 1;
        }

        // Remove the last element
        _trustedIssuers.pop();

        // Reset the index
        delete _trustedIssuerIndex[trustedIssuer];

        // Reset the claim topics
        delete _trustedIssuerClaimTopics[trustedIssuer];

        emit TrustedIssuerRemoved(trustedIssuer);
    }

    /**
     * @dev Updates the claim topics of a trusted issuer
     * @param trustedIssuer Address of the trusted issuer
     * @param claimTopics New array of claim topics
     */
    function updateIssuerClaimTopics(address trustedIssuer, uint256[] calldata claimTopics) external onlyOwner {
        require(_trustedIssuerIndex[trustedIssuer] != 0, "TrustedIssuersRegistry: Not registered");
        require(claimTopics.length > 0, "TrustedIssuersRegistry: Empty claim topics");

        _trustedIssuerClaimTopics[trustedIssuer] = claimTopics;

        emit TrustedIssuerClaimTopicsUpdated(trustedIssuer, claimTopics);
    }

    /**
     * @dev Checks if an address is a trusted issuer
     * @param issuer Address to check
     * @return True if the address is a trusted issuer
     */
    function isTrustedIssuer(address issuer) external view returns (bool) {
        return _trustedIssuerIndex[issuer] != 0;
    }

    /**
     * @dev Gets the claim topics a trusted issuer can issue
     * @param trustedIssuer Address of the trusted issuer
     * @return Array of claim topics
     */
    function getTrustedIssuerClaimTopics(address trustedIssuer) external view returns (uint256[] memory) {
        require(_trustedIssuerIndex[trustedIssuer] != 0, "TrustedIssuersRegistry: Not registered");

        return _trustedIssuerClaimTopics[trustedIssuer];
    }

    /**
     * @dev Gets the list of all trusted issuers
     * @return Array of trusted issuer addresses
     */
    function getTrustedIssuers() external view returns (address[] memory) {
        return _trustedIssuers;
    }

    /**
     * @dev Gets the number of trusted issuers
     * @return Number of trusted issuers
     */
    function getTrustedIssuersCount() external view returns (uint256) {
        return _trustedIssuers.length;
    }
}

